with base as (select id, store_id, sale_date, units, revenue, round(revenue / units, 2) as revenue_per_unit from store_sales where sale_date > date '2023-06-08'), scored as (select *, lead(units) over w_hist as next_units, lag(revenue_per_unit) over w_hist as prev_revenue_per_unit, row_number() over w_hist as event_seq from base window w_hist as (partition by store_id order by revenue asc, id asc)), latest as (select id, sale_date, revenue, revenue_per_unit, prev_revenue_per_unit, event_seq from (select *, row_number() over (partition by store_id order by sale_date desc nulls last, id asc) as rn from scored) x where rn = 1), base_store_sales as (select *, last_day(sale_date) as sale_date_month_end, round(event_seq, 1) as event_seq_rounded from latest where sale_date > date '2023-04-09') select id, sale_date, revenue_per_unit, prev_revenue_per_unit, sale_date_month_end, event_seq_rounded from base_store_sales order by sale_date_month_end asc nulls last, id asc
